import { attachSaveStatus } from "./save-status.js";
import { createTrailingTask } from "./trailing-task.js";

export function createDraftEditor({ store, timers, renderDocument, renderStatus }) {
  let current = null;
  let navigation = 0;

  // Retire the status listener before saving. Saving notifies subscribers
  // synchronously, and an integration is allowed to navigate from there.
  function leave() {
    const leaving = current;
    current = null;
    renderDocument(null);
    if (leaving) {
      leaving.stop();
      leaving.save.flush();
    }
  }

  function close() {
    ++navigation;
    leave();
  }

  return {
    open(id) {
      const request = ++navigation;
      leave();
      // A save callback may have made a newer navigation request.
      if (request !== navigation) return;
      current = {
        id,
        stop: attachSaveStatus(store, id, renderStatus),
        save: createTrailingTask(text => store.write(id, text), 120, timers),
      };
      renderDocument({ id, text: store.read(id) });
    },
    edit(text) {
      if (current) current.save.push(text);
    },
    close,
  };
}

